// A const member function using a mutex for thread-safe caching.
class Widget {
public:
  int magicValue() const {
    // guard ensures mutex is locked and automatically unlocked
    std::lock_guard<std::mutex> guard(m);

    if (cacheValid) {
      return cachedValue;
    }

    // If cache is invalid, compute, update, and return
    auto val1 = 100; // expensiveComputation1();
    auto val2 = 200; // expensiveComputation2();
    cachedValue = val1 + val2;
    cacheValid = true;
    return cachedValue;
  }

private:
  mutable std::mutex m;
  mutable int cachedValue;      // mutable: can be changed in const methods
  mutable bool cacheValid{false}; // mutable: can be changed in const methods
};
